    if (ap_rst_n_inv == 1'b1) begin
        ap_CS_fsm <= ap_ST_fsm_state1;
    end else begin
        ap_CS_fsm <= ap_NS_fsm;
    end
end

always @ (posedge ap_clk) begin
    if (ap_rst_n_inv == 1'b1) begin
        grp_k1_vertex_transform_fu_180_ap_start_reg <= 1'b0;
    end else begin
        if (((1'b1 == ap_CS_fsm_state1) & (ap_start == 1'b1))) begin
            grp_k1_vertex_transform_fu_180_ap_start_reg <= 1'b1;
        end else if ((grp_k1_vertex_transform_fu_180_ap_ready == 1'b1)) begin
            grp_k1_vertex_transform_fu_180_ap_start_reg <= 1'b0;
        end
    end
end

